CREATE TABLE IF NOT EXISTS mp_catalog_contract_revisions(version integer PRIMARY KEY,expected_count integer NOT NULL,digest text NOT NULL,owner_authorization text NOT NULL,evidence_snapshot text NOT NULL,approved_catalogue jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mp_league_source_observations(league_id text NOT NULL REFERENCES mp_leagues(id),source_id text NOT NULL CHECK(source_id IN ('statistiche_lega','backtest_storico')),snapshot_id text NOT NULL REFERENCES matchpilot_source_snapshots(snapshot_id),source_name text NOT NULL,source_value text NOT NULL,sample_count integer NOT NULL CHECK(sample_count>=0),observed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(league_id,source_id,snapshot_id));
CREATE OR REPLACE VIEW mp_league_provenance AS SELECT l.id,l.name,t.name AS territory,array_agg(DISTINCT o.source_id) FILTER(WHERE o.source_id IS NOT NULL) AS sources FROM mp_leagues l JOIN mp_territories t ON t.id=l.territory_id LEFT JOIN mp_league_source_observations o ON o.league_id=l.id GROUP BY l.id,l.name,t.name;
